package com.agriconnect.order;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;@RestController class AnalyticsExportController{private final JdbcClient db;AnalyticsExportController(JdbcClient d){db=d;}@GetMapping("/internal/analytics/orders")List<Map<String,Object>>rows(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){return db.sql("select id as \"orderId\",buyer_id as \"buyerId\",total_amount as \"totalAmount\",status from orders order by id limit :s offset :o").param("s",size).param("o",page*size).query().listOfRows();}}
